{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2172-02-05 20:00:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee, one of the surgery team doctors. You’re here because you had sudden abdominal pain after stepping on your feeding tube?"
    },
    {
      "turn_number": 2,
      "time": "2172-02-05 20:02:00",
      "speaker": "Patient",
      "text": "Yes, exactly. I tripped on the tube three days ago, felt a sharp tug, and the pain hasn’t gone away. The area around the tube is also more red and has this yellow discharge."
    },
    {
      "turn_number": 3,
      "time": "2172-02-05 20:04:00",
      "speaker": "Doctor",
      "text": "I see. And are you having nausea, vomiting, or any fever?"
    },
    {
      "turn_number": 4,
      "time": "2172-02-05 20:05:00",
      "speaker": "Patient",
      "text": "No, no fever or vomiting. Feeds are going in okay, but the skin around the tube is really irritated."
    },
    {
      "turn_number": 5,
      "time": "2172-02-05 20:07:00",
      "speaker": "Doctor",
      "text": "Okay, thanks. We’re going to keep you NPO for now—no tube feeds—just to be safe. We’ll start IV fluids and get some imaging to make sure the tube hasn’t moved or caused a leak."
    },
    {
      "turn_number": 6,
      "time": "2172-02-05 20:09:00",
      "speaker": "Patient",
      "text": "Will they do that tonight?"
    },
    {
      "turn_number": 7,
      "time": "2172-02-05 20:11:00",
      "speaker": "Doctor",
      "text": "Yes, the radiology team is already setting up a G-tube study. They’ll inject a little contrast to see where it goes and check if there’s any leakage outside the stomach."
    },
    {
      "turn_number": 8,
      "time": "2172-02-05 21:30:00",
      "speaker": "Doctor",
      "text": "Good news—the scan is back. The tube is in the right place, and the contrast went straight into your stomach and then into the small bowel. No signs of a leak."
    },
    {
      "turn_number": 9,
      "time": "2172-02-05 21:32:00",
      "speaker": "Patient",
      "text": "Oh, that’s a relief. So nothing tore or came loose?"
    },
    {
      "turn_number": 10,
      "time": "2172-02-05 21:34:00",
      "speaker": "Doctor",
      "text": "No, the internal part looks intact. But we did see some irritation and granulation tissue at the skin site, which is likely why it’s painful and draining."
    },
    {
      "turn_number": 11,
      "time": "2172-02-05 21:36:00",
      "speaker": "Patient",
      "text": "Is that the same thing that happened before, when they found a suture stuck in the wound?"
    },
    {
      "turn_number": 12,
      "time": "2172-02-05 21:38:00",
      "speaker": "Doctor",
      "text": "Similar, but this time it’s not a foreign body. It’s just the body’s way of healing—sometimes too much tissue forms. We’ll manage it with better wound care and frequent dressing changes."
    },
    {
      "turn_number": 13,
      "time": "2172-02-06 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs are normal—no infection signs. We’re going to restart your tube feeds slowly and see how you tolerate it."
    },
    {
      "turn_number": 14,
      "time": "2172-02-06 08:02:00",
      "speaker": "Patient",
      "text": "And the pain? It’s better, but still there when I touch it."
    },
    {
      "turn_number": 15,
      "time": "2172-02-06 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep giving you pain meds as needed. The discomfort should improve as the skin irritation resolves. The redness has already gotten much better with proper care."
    },
    {
      "turn_number": 16,
      "time": "2172-02-06 10:00:00",
      "speaker": "Doctor",
      "text": "You’ve been tolerating the feeds well, no nausea, and your pain is controlled. We’re planning to discharge you today."
    },
    {
      "turn_number": 17,
      "time": "2172-02-06 10:02:00",
      "speaker": "Patient",
      "text": "Great. Should I do anything different at home with the tube?"
    },
    {
      "turn_number": 18,
      "time": "2172-02-06 10:04:00",
      "speaker": "Doctor",
      "text": "Keep doing frequent dressing changes, and watch for increased redness, swelling, or foul-smelling discharge. You’ll follow up with Dr. ___ in two weeks—he may consider repositioning the tube if the granulation tissue persists."
    },
    {
      "turn_number": 19,
      "time": "2172-02-06 10:06:00",
      "speaker": "Patient",
      "text": "Okay, and I can keep taking my regular medications?"
    },
    {
      "turn_number": 20,
      "time": "2172-02-06 10:08:00",
      "speaker": "Doctor",
      "text": "Yes, all your home meds are continued, including the mupirocin for MRSA and your vitamins. We’re adding a stool softener to help with bowel movements."
    },
    {
      "turn_number": 21,
      "time": "2172-02-06 10:10:00",
      "speaker": "Patient",
      "text": "Thank you. I was really worried something serious happened."
    },
    {
      "turn_number": 22,
      "time": "2172-02-06 10:12:00",
      "speaker": "Doctor",
      "text": "I understand. But you’re stable, healing, and safe to go home. Just call if you develop fever, severe pain, or trouble with the tube."
    },
    {
      "turn_number": 23,
      "time": "2172-02-06 12:00:00",
      "speaker": "Doctor",
      "text": "Your discharge orders are ready. You’ll get written instructions and prescriptions before you leave."
    },
    {
      "turn_number": 24,
      "time": "2172-02-06 12:02:00",
      "speaker": "Patient",
      "text": "Got it. I’ll make sure to keep the site clean and dry."
    },
    {
      "turn_number": 25,
      "time": "2172-02-06 12:04:00",
      "speaker": "Doctor",
      "text": "Exactly. And keep up with the follow-up. We want to make sure this doesn’t keep happening."
    },
    {
      "turn_number": 26,
      "time": "2172-02-06 14:00:00",
      "speaker": "Doctor",
      "text": "Just checking in one last time. Still doing well? No new symptoms?"
    },
    {
      "turn_number": 27,
      "time": "2172-02-06 14:02:00",
      "speaker": "Patient",
      "text": "Yes, still feeling okay. Ready to go home."
    },
    {
      "turn_number": 28,
      "time": "2172-02-06 14:04:00",
      "speaker": "Doctor",
      "text": "Perfect. Take care, and we’ll see you in clinic soon."
    }
  ],
  "summary": {
    "admission_start": "2172-02-05 19:53:00",
    "admission_end": "2172-02-06 17:45:00",
    "summary_paragraph": "The patient was admitted after experiencing persistent abdominal pain and increased discharge from her G-tube following an incident where she stepped on the tube. Initial evaluation raised concern for possible dislodgement or perforation, so she was kept NPO and underwent a G-tube sinogram, which confirmed the tube was correctly positioned with no evidence of leakage. She was restarted on tube feeds, which she tolerated well, and her skin erythema improved with proper wound care. Pain was managed with medication, and she remained stable throughout the admission. She was discharged home with instructions for ongoing wound care, medication management, and follow-up with surgery clinic for possible tube repositioning.",
    "problems": [
      "Mechanical complication of gastrostomy",
      "Other specified procedures as the cause of abnormal reaction of patient, or of later complication, without mention of misadventure at time of procedure",
      "Home accidents",
      "Polycystic ovaries"
    ]
  }
}
